#!/usr/bin/env python3
"""Pure geometry and exact rational bounds; no solver, equilibrium, or checker run."""
from pathlib import Path
from fractions import Fraction as Q
from decimal import Decimal,localcontext,ROUND_FLOOR
import json,math,hashlib,argparse
H=Path(__file__).resolve().parent;ROOT=H.parents[4];PIN=H.parent/'search/runtime'
SRC={'visibility':PIN/'src/stowage/checker/visibility.py','axes':PIN/'src/stowage/vessel/hydrostatics.py','loading_limits':PIN/'src/stowage/checker/stability.py','stability_loading':PIN/'src/stowage/checker/stability_loading.py','stability_equilibrium':PIN/'src/stowage/checker/stability_equilibrium.py'}
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def dot(a,b):return math.fsum(x*y for x,y in zip(a,b))
def sub(a,b):return [x-y for x,y in zip(a,b)]
def scale(a,t):return [x*t for x in a]
def cross(a,b):return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]
def norm(a):return math.sqrt(dot(a,a))
def clip(poly,fn):
 result=[]
 for p,q in zip(poly,poly[1:]+poly[:1]):
  a,b=fn(p),fn(q)
  if a>=0:result.append(p)
  if (a>=0)!=(b>=0):result.append([p[i]+a/(a-b)*(q[i]-p[i])for i in range(3)])
 return result

def frame(d,pose):
 b,h=d['vessel']['bridge'],d['vessel']['hull'];ta,tf,heel=[pose[k]for k in('draught_aft_m','draught_fwd_m','list_rad')];s=(tf-ta)/h['lpp_m'];n=[-s*math.cos(heel),-math.sin(heel),math.cos(heel)];n=scale(n,1/norm(n));u=sub([1.,0.,0.],scale(n,n[0]));u=scale(u,1/norm(u));v=cross(n,u);E=[b['x_m']-2.,0.,b['eye_z_m']];height=dot(n,E)-n[2]*ta;bowz=ta+s*b['bow_x_m'];bow=dot(u,sub([b['bow_x_m'],0.,bowz],E));limit=min(2*h['loa_m'],500.);R=bow+limit;q=[height*u[i]+R*n[i]for i in range(3)]
 return {'n':n,'u':u,'v':v,'E':E,'height':height,'bow':bow,'limit':limit,'range':R,'q':q,'ta':ta,'s':s,'heel':heel}
def transform(f,p):
 a=sub(p,f['E']);return [dot(f['u'],a),dot(f['v'],a),dot(f['n'],a)+f['height']]
def blind(f,o,top=None):
 z=o['top']if top is None else top;wedge=math.tan(math.radians(10));x,y,l,w=[o[k]for k in('x','y','length','width')];ps=[transform(f,[xx,yy,z])for xx,yy in((x-l/2,y-w/2),(x+l/2,y-w/2),(x+l/2,y+w/2),(x-l/2,y+w/2))];ps=clip(clip(clip(ps,lambda p:p[0]-1e-9),lambda p:wedge*p[0]-p[1]),lambda p:wedge*p[0]+p[1]);return max([0.]+[math.inf if p[2]>=f['height']-1e-10 else f['height']*p[0]/(f['height']-p[2])-f['bow']for p in ps if p[2]>0])
def cap(f,o):
 E,q=f['E'],f['q'];assert q[2]>0;points=[]
 for x in(o['x']-o['length']/2,o['x']+o['length']/2):
  for y in(o['y']-o['width']/2,o['y']+o['width']/2):points.append((E[2]-(q[0]*(x-E[0])+q[1]*(y-E[1]))/q[2],x,y))
 z,x,y=min(points)
 for zz in(z,o['top']):
  p=transform(f,[x,y,zz]);assert p[0]>0 and abs(p[1])<=math.tan(math.radians(10))*p[0]
 assert math.isclose(blind(f,o,z),f['limit'],abs_tol=1e-7)
 assert blind(f,o,z+.001)>f['limit']
 return {'slot':o['slot'],'container_id':o['container_id'],'top_m':o['top'],'bottom_m':o['bottom'],'allowable_roof_top_m':z,'minimum_lowering_m':max(0.,o['top']-z),'critical_corner':[x,y,z],'isolated_blind_current_m':blind(f,o),'isolated_blind_at_cap_m':blind(f,o,z),'isolated_blind_after_one_standard_tier_m':blind(f,o,o['top']-2.591)}
def parts(s):
 b,r,t=int(s[:3]),int(s[3:5]),int(s[5:]);return [s]if b%2 else[f'{k:03}{r:02}{t:02}'for k in(b-1,b+1)]
def supported(d,raw):
 assert not d['onboard']['placements'];moves=raw['plan']['moves'];assert {m['kind']for m in moves}<={'load','relocate','hatch_cover_off','hatch_cover_on'};loads=[m for m in moves if m['kind']=='load'];assert len(loads)==len(d['load_list']);assert {m['container_id']for m in loads}==set(d['load_list']);boxes={b['id']:b for b in d['containers']};cells={c['id']:c for c in d['vessel']['cells']};stacks={s['id']:s for s in d['vessel']['stacks']};tops={sid:s['base_z_m']for sid,s in stacks.items()};occupied=set();result={};lineage={sid:[]for sid in stacks}
 for move in sorted(loads,key=lambda m:(int(m['dst'][-2:]),m['dst'])):
  slot,cid=move['dst'],move['container_id'];box=boxes[cid];ps=parts(slot);assert len(ps)==(1 if box['length_ft']==20 else 2);floors=[]
  for c in ps:
   assert c not in occupied;cell=cells[c];seq=stacks[cell['stack_id']]['cell_ids'];i=seq.index(c);assert i==0 or seq[i-1]in occupied;floors.append(tops[cell['stack_id']])
  assert max(floors)-min(floors)<1e-6;bottom=floors[0];top=bottom+box['height_m']+(box['oog']['over_height_m']if box['oog']else 0.);extra=box['oog']or{};fore=extra.get('over_length_fore_m',0);aft=extra.get('over_length_aft_m',0);port=extra.get('over_width_port_m',0);star=extra.get('over_width_starboard_m',0);x=math.fsum(cells[c]['lcg_m']/len(ps)for c in ps)+(fore-aft)/2;y=math.fsum(cells[c]['tcg_m']/len(ps)for c in ps)+(port-star)/2;o={'slot':slot,'container_id':cid,'bottom':bottom,'top':top,'x':x,'y':y,'length':{20:6.058,40:12.192,45:13.716}[box['length_ft']]+fore+aft,'width':2.438+port+star};result[slot]=o
  for c in ps:
   occupied.add(c);sid=cells[c]['stack_id'];tops[sid]=top;lineage[sid].append({'slot':slot,'container_id':cid,'height_m':box['height_m'],'bottom_m':bottom,'top_m':top})
 return result,lineage

def dec(q):
 with localcontext()as c:c.prec=60;c.rounding=ROUND_FLOOR;return str(Decimal(q.numerator)/Decimal(q.denominator))
def rational_certificate():
 f=Q;exlo,exhi=f('10.440999999'),f('10.441000001');ezlo,ezhi=f('29.299999999'),f('29.300000001');oxlo,oxhi=f('82.300999999'),f('82.301000001');oyhi=f('9.969000001');ozlo,ozhi=f('26.674999999'),f('26.675000001');ta=f('8.700000001');sm=f('.01000000002');qm=f('.035');L=f('268.88000002');bhi=f('129.425000001');blo=f('129.424999999');theta=f('.034906586');tan_bound=theta/(1-theta*theta/2);assert tan_bound<qm
 dxlo,dxhi=oxlo-exhi,oxhi-exlo;dzlo,dzhi=ozlo-ezhi,ozhi-ezlo;dl=dzlo-sm*dxhi-qm*oyhi;du=dzhi+sm*dxhi+qm*oyhi;T=ezlo-ta-sm*exhi;R=bhi-exlo+L;F=T*dxlo+R*dl;den=(1+(sm*sm+qm*qm)/2)*(1+qm*qm/2);Xlo=(dxlo-sm*qm*oyhi-sm*(ezhi-ozlo))/den;Yhi=oyhi+qm*(ezhi-ozlo);wedge=f('.1745')*Xlo-Yhi;above=ozlo-ta-sm*oxhi-qm*oyhi;bowlo=(blo-exhi-sm*(ezhi+sm*exhi))/den
 assert dl<du<0 and T>0 and R>0 and F>f('40')and Xlo>0 and wedge>0 and above>0 and bowlo>0
 vals={'s_abs_upper':sm,'tan_heel_abs_upper':qm,'heel_rad_upper_for_tan_proof':theta,'sin_cos_tan_upper':tan_bound,'aft_draught_upper_m':ta,'blind_limit_upper_m_including_tolerance':L,'dx_lower_m':dxlo,'dx_upper_m':dxhi,'delta_lower_m':dl,'delta_upper_m':du,'T_lower_m':T,'R_upper_m':R,'F_lower_m2':F,'X_lower_m':Xlo,'absY_upper_m':Yhi,'wedge_linear_clearance_lower_m':wedge,'roof_above_water_numerator_lower_m':above,'bow_projection_lower_m':bowlo,'blind_distance_excess_lower_m':F/(-dl),'necessary_lowering_lower_bound_m':F/R}
 return {'exact_rational_bounds':{k:{'numerator':str(v.numerator),'denominator':str(v.denominator),'decimal_rounded_down':dec(v)}for k,v in vals.items()},'input_coordinate_enclosures_m':{'eye_x':[str(exlo),str(exhi)],'eye_z':[str(ezlo),str(ezhi)],'vertex_x':[str(oxlo),str(oxhi)],'vertex_y':['9.968999999',str(oyhi)],'vertex_z':[str(ozlo),str(ozhi)],'bow_x':[str(blo),str(bhi)]},'wedge_slope_lower':'.1745','algebra':'F=(Ez-ta-s*Ex)*dx + (dB+L*a)*(-s*dx-q*y+dz); a=sqrt((1+q*q)/(1+s*s+q*q)); q=tan(heel).','conclusion':'For the fixed supported vertex, every pose inside this optimistic loading-limit box violates blind distance. This is a conditional fixed-stow geometry certificate, not a full-checker/all-ballast or map infeasibility certificate.'}

def build():
 manifestp=ROOT/'experiments/mvp/strategy/blockrule/cohort-medium.json';manifest=json.loads(manifestp.read_text());tasks_p=H.parent/'finisher/tasks.json';tasks=json.loads(tasks_p.read_text());attrp=H.parent/'finisher/visibility-attribution.json';attrs=json.loads(attrp.read_text());cert=rational_certificate();rows=[]
 for task in tasks:
  job=next(j for j in manifest['maps']if j['map_id']==task['map_id']);assert job['split']=='train'and job['seed']in(185100100,185100111);inp=ROOT/job['input'];assert sha(inp)==job['sha256'];d=json.loads(inp.read_text());rawp=ROOT/task['raw_result'];raw=json.loads(rawp.read_text());geometry,lineage=supported(d,raw);o=geometry['0100890'];assert all(abs(o[k]-v)<1e-9 for k,v in {'x':76.205,'y':8.75,'top':26.675,'length':12.192,'width':2.438}.items());O=[o['x']+o['length']/2,o['y']+o['width']/2,o['top']];assert all(abs(x-y)<1e-9 for x,y in zip(O,[82.301,9.969,26.675]));h=d['vessel']['hull'];bridge=d['vessel']['bridge'];assert not d['rule_overrides'];assert Q(str(max(abs(h['min_trim_m']),h['max_trim_m'])))+Q('.00000000011') < Q('.01000000002')*(Q(str(h['lpp_m']))-Q('.000000001'));assert Q(str(h['max_list_rad']))+Q('.00000000011')<Q('.034906586');assert Q(str(h['max_draught_m']))+Q('.00000000011')<Q('8.700000001');assert h['min_draught_fwd_m']-h['max_trim_m']>0;assert bridge=={'bow_x_m':129.425,'eye_z_m':29.3,'x_m':12.441};attribute=next(r for r in attrs if r['map_id']==job['map_id']);reportp=ROOT/'experiments/mvp/strategy/blockrule/runs/initial-medium-train/maps'/job['map_id']/'reports/default-raw.json';assert sha(reportp)==attribute['report_sha256'];report=json.loads(reportp.read_text());phases=[]
  for name,phase in attribute['conditions'].items():
   f=frame(d,phase['pose']);allgroup=phase['groups']['all'];top5=allgroup['dominant_blind_obstacles'];assert top5[0]['slot']=='0100890';assert math.isclose(blind(f,o),allgroup['blind_distance_m'],abs_tol=1e-8);q=f['q'];E=f['E'];candidates=[]
   for old in top5:
    actual=geometry[old['slot']];assert actual['container_id']==old['container_id'];assert all(math.isclose(actual[k],old[k],abs_tol=1e-9)for k in('x','y','bottom','top','length','width'));assert math.isclose(blind(f,actual),old['blind_distance_m'],abs_tol=1e-8);candidates.append(cap(f,actual))
   # Check the reduced F against the original transformed sightline inequality.
   dx,dy,dz=sub(O,E);s,heel=f['s'],f['heel'];qq=math.tan(heel);a=math.sqrt((1+qq*qq)/(1+s*s+qq*qq));T=E[2]-f['ta']-s*E[0];F=T*dx+(bridge['bow_x_m']-E[0]+f['limit']*a)*(-s*dx-qq*dy+dz);G=dot(q,sub(O,E));assert math.isclose(F,G*math.sqrt(1+qq*qq),rel_tol=1e-11,abs_tol=1e-8)
   stab=report['parts'][name.removesuffix('visibility')+'stability']['metrics'];pose_gap={k:phase['pose'][k]-stab[k]for k in('draught_aft_m','draught_fwd_m','list_rad')};pose_gap['trim_m']=phase['pose']['draught_aft_m']-phase['pose']['draught_fwd_m']-stab['trim_m']
   phases.append({'stability_pose':{k:stab[k]for k in('draught_aft_m','draught_fwd_m','trim_m','list_rad')},'visibility_minus_stability_pose':pose_gap,'condition':name,'pose':phase['pose'],'stored_full_scene_blind_m':allgroup['blind_distance_m'],'limit_m':f['limit'],'height_eye_above_water_m':f['height'],'eye_to_bow_projected_m':f['bow'],'range_boundary_m':f['range'],'roof_plane':{'intercept_m':E[2]+q[0]*E[0]/q[2],'slope_x':-q[0]/q[2],'slope_y':-q[1]/q[2],'expression':'z_max = intercept_m + slope_x*x + slope_y*y'},'dominant':candidates[0],'top_five':candidates,'sectors_still_separate':{'max_blind_sector_rad':allgroup['max_blind_sector_rad'],'total_blind_sector_rad':allgroup['total_blind_sector_rad'],'min_clear_sector_rad':allgroup['min_clear_sector_rad']},'F_original_vs_reduced_agree':True})
  rows.append({'map_id':job['map_id'],'input':job['input'],'input_sha256':sha(inp),'raw_plan_result':task['raw_result'],'raw_result_sha256':sha(rawp),'checked_report':str(reportp.relative_to(ROOT)),'checked_report_sha256':sha(reportp),'supported_critical_obstacle':o,'critical_vertex_m':O,'support_lineage':{sid:lineage[sid]for sid in('00908D','01108D')},'loading_limits':{k:h[k]for k in('min_trim_m','max_trim_m','max_draught_m','min_draught_fwd_m','max_list_rad','lpp_m','loa_m')},'rule_overrides':d['rule_overrides'],'freeze_contract':'OFF; D191 existing solved layouts and loading limits; geometry certificate independent of ballast recipe','phases':phases})
 gapmax={k:max(abs(phase['visibility_minus_stability_pose'][k])for r in rows for phase in r['phases'])for k in('draught_aft_m','draught_fwd_m','trim_m','list_rad')}
 return {'cross_checker_pose_equivalence_proved':False,'full_checker_infeasibility_certified':False,'all_ballast_failure_certified':False,'observed_six_pose_gap_maxima':gapmax,'pose_compatibility_gap':'Visibility direct all-tank centroid equilibrium and stability small-tank-exempt/table-assisted equilibrium are distinct. No universal transfer/error bound is established. The policy-admissible-pose certificate is geometric and conditional.','format':'medium-wall-fixed-roof-v1','script_sha256':sha(__file__),'source_sha256':{k:{'path':str(p.relative_to(ROOT)),'sha256':sha(p)}for k,p in SRC.items()},'attribution_json_sha256':sha(attrp),'attribution_script_sha256':sha(H.parent/'finisher/visibility_attribution.py'),'tasks_sha256':sha(tasks_p),'cohort_sha256':sha(manifestp),'worker_reservation':'No new compute worker; pure geometry/standard-library rational arithmetic. No equilibrium, LP, CP, finisher or checker invoked.','source_equations':{'axes':'hydrostatics.py:400-410, n ∝ (-s,-tan(heel),1)','visibility':'visibility.py:360-374,407-426: H*X/(H-h)-bow <= L','loading_limits':'stability.py:475-525,719-735; overrides may tighten, checker tolerance1e-10','blind_distance_tolerance':'visibility.py:449 uses 1e-8m'},'policy_admissible_pose_certificate':cert,'maps':rows,'scope':'Two exact existing feeder800 cargo stows only. A different cargo stow may be feasible; no map-level infeasibility claim. Angular-sector constraints separately bind.'}

def markdown(p):
 lines=['# Visibility roof target and conditional geometric certificate','', 'Both existing feeder_800 layouts contain the same critical supported roof vertex at **(82.301, 9.969, 26.675) m**, in slot `0100890`. These exact fixed stows cannot satisfy the blind-distance rule at any visibility pose meeting their declared draft, trim and list limits. This is a conditional geometric certificate. It does not establish full-checker failure for every ballast vector, or map infeasibility; the stability-to-visibility pose compatibility gap is explicit below.','', '## Targets at the stored checker poses','', '| Train seed | Condition | Stored blind distance | Allowed roof top at critical footprint | Minimum roof lowering | Blind distance after one 2.591 m tier lowering |','|---|---|---:|---:|---:|---:|']
 for row in p['maps']:
  for phase in row['phases']:
   name=phase['condition'];phase_name='mid-voyage'if'mid_voyage'in name else 'arrival'if'arrival'in name else 'departure';a=phase['dominant'];lines.append(f"| {row['map_id'].split('-')[-1]} | {phase_name} | {phase['stored_full_scene_blind_m']:.3f} m | {a['allowable_roof_top_m']:.6f} m | {a['minimum_lowering_m']:.6f} m | {a['isolated_blind_after_one_standard_tier_m']:.3f} m |")
 lines+=['','The blind-distance allowance is 268.88 m. A forward roof-plane cap that covers all three stored poses is **25.993266 m** on random100 and **24.989386 m** on simulated111 at this footprint. The actual roof is 26.675 m; its top box is standard height 2.591 m with bottom 24.084 m. Moving that box to a suitable location would lower this local roof sufficiently at the stored poses. Other high forward boxes also exceed their roof caps: the JSON retains the top-five obstacle targets for every pose. Removing or lowering only the dominant obstacle does not certify the full scene, and the angular sector rules still require a separate check. No cargo move or altered ballast state was simulated.','', '## Exact source geometry','', 'Let `E` be the conning eye, `n` the unit waterplane normal, `u` the unit forward axis projected onto that waterplane, `H = n·E − n_z*t_a`, `b` the projected eye-to-bow distance, and `R=b+L`, with `L=min(2*LOA,500)=268.88 m`. For a roof point `P`, the source computes `X=u·(P−E)` and `h=n·(P−E)+H`, then blind distance `H*X/(H−h)−b`. For a point below the eye, blind distance ≤L is equivalent to','', '`(H*u + R*n) · (P−E) ≤ 0`.','', 'Thus the allowable roof is the plane `z_max = E_z − [w_x(x−E_x)+w_y(y−E_y)]/w_z`, where `w=H*u+R*n`. The reported cap minimizes this plane over the rectangle corners. Its critical forward/port corner remains inside the forward ten-degree wedge at both the actual and limiting heights, so this cap is necessary and sufficient for this isolated rectangle’s blind-distance condition at the fixed pose. Roof heights, full support lineage and all six stored blind distances are independently reconstructed from the actual serialized load moves and instance cell/stack geometry.','', 'Pinned source: [visibility transform and sightline](../search/runtime/src/stowage/checker/visibility.py), lines 360–374 and 407–426; [waterplane axes](../search/runtime/src/stowage/vessel/hydrostatics.py), lines 400–410. The JSON pins source, raw-plan, input, checked-report and attribution hashes.','', '## All permitted poses: outward certificate','', 'The actual per-instance bounds are aft/forward draft ≤8.7 m, signed trim within [−1.2441,+1.2441] m, Lpp=124.41 m, and |heel|≤2°. There are no instance rule overrides. Forward minimum draft 3.045 m and the trim bound imply aft draft >0. The pinned [loading-limit checks](../search/runtime/src/stowage/checker/stability.py), lines 719–735, allow numerical tolerance 1e-10; the bounds below include it. Both source layouts have exactly the supported critical roof above.','', 'Set `s=(t_f−t_a)/Lpp`, `q=tan(heel)`, `a=sqrt((1+q²)/(1+s²+q²))`, `dx=O_x−E_x`, `dz=O_z−E_z`, and `dB=bow_x−E_x`. The source axes give `n ∝ (−s,−q,1)`, so the correct sign of the transverse term is **−q*O_y**. Cancelling the transformed coordinates yields the equivalent inequality','', '`F = (E_z−t_a−s*E_x)*dx + (dB+L*a)*(−s*dx−q*O_y+dz) ≤ 0`.','', 'The certificate widens the permitted set to independent bounds `0≤t_a≤8.700000001`, `|s|≤0.01000000002`, and `|q|≤0.035`; it deliberately omits the additional forward-draft coupling. Since `sin(x)≤x` and `cos(x)≥1−x²/2`, even the outward heel bound 0.034906586 rad has `tan(x)≤x/(1−x²/2)<0.035`. Coordinates are enclosed outwards by 1e-9 m, and the blind limit is enlarged to 268.88000002 m to include its 1e-8 m checker tolerance. All subsequent bound arithmetic uses exact rational numbers.','', 'With `T=E_z−t_a−s*E_x` and `Δ=−s*dx−q*O_y+dz`, the enclosure has `T>0`, `Δ∈[−3.692515004,−1.557484996]<0`, and `a≤1`. Therefore `F ≥ T_min*dx_min + R_max*Δ_min`. The exact rational result gives **F >40.61945 m²**, retaining more than 40 m² of strict sign margin. The same enclosure gives forward `X>71.73876 m` and transverse `|Y|<10.06088 m`; even the conservative wedge slope 0.1745 leaves >2.45753 m of clearance. The vertex is always inside the checked forward wedge, remains above the water and below the eye, and has positive eye/bow projections. This is an interval argument over the entire optimistic pose box, not sampling or a bounded solver failure.','', 'It also yields a conservative blind-distance excess **>11.00048 m**, and at least **0.104726 m** of roof lowering at this same x/y is necessary even in that optimistic pose box. The latter is only a lower bound: it does not prove that one complete tier is necessary, or that a 0.105 m change suffices. At the six actual stored poses, the required lowering is larger, as shown above.','', 'If the visibility pose obeys those declared loading limits, the unchanged roofs require a cargo height/position change: extra search cannot alter this conditional geometric obstruction. However the unchanged full checker computes stability and visibility poses by distinct numerical paths, and this audit establishes no all-ballast transfer bound. Therefore it does not prove that every ballast vector fails the full checker. Repacking the forward high roofs is a concrete candidate direction, preserving every cargo box; all geometry, sector, stability, strength and securing checks remain necessary. Other stows on these maps remain unclassified.','', '## Pose compatibility gap', '', 'Visibility `_loading_condition` (visibility.py:251–313) iterates direct equilibrium with all tank centroids. Stability uses `loading_condition(..., small_tank_exemption=True)` (stability.py:612–614), then its table/direct floating-equilibrium path (stability.py:617–650). These are not proven identical. The six existing checked examples have maximum absolute aft-draft discrepancy '+format(p['observed_six_pose_gap_maxima']['draught_aft_m'],'.9f')+' m, trim discrepancy '+format(p['observed_six_pose_gap_maxima']['trim_m'],'.9f')+' m, and list discrepancy '+format(p['observed_six_pose_gap_maxima']['list_rad'],'.9g')+' rad. These finite observations disprove exact pose identity but do not provide a universal error bound. A stability-passing pose cannot automatically be substituted for the visibility pose in this certificate. No unconditional fixed-stow/full-checker/all-ballast infeasibility claim follows.', '', '## Reproduce and verify','', 'Run `.venv/bin/python experiments/mvp/strategy/medium-wall/capacity/visibility_roof.py --verify`. It uses only standard-library geometry and exact rational arithmetic, reads the two existing train inputs/plans and stored checker attribution, and checks its generated JSON/Markdown byte-for-byte. There is no new equilibrium solve, CP/LP search, finisher run, full-checker call, map generation or source edit. The CPU reservation remains with the finisher.']
 return'\n'.join(lines)+'\n'
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--verify',action='store_true');a=ap.parse_args();p=build();j=json.dumps(p,indent=2,sort_keys=True)+'\n';md=markdown(p)
 if a.verify:assert(H/'visibility-roof.json').read_text()==j;assert(H/'VISIBILITY-ROOF.md').read_text()==md
 else:(H/'visibility-roof.json').write_text(j);(H/'VISIBILITY-ROOF.md').write_text(md)
 print(json.dumps({'verified':a.verify,'fixed_stows':2,'stored_poses_reproduced':6,'geometry_caps_checked':30,'F_lower_m2':p['policy_admissible_pose_certificate']['exact_rational_bounds']['F_lower_m2']['decimal_rounded_down'],'json_sha256':sha(H/'visibility-roof.json'),'markdown_sha256':sha(H/'VISIBILITY-ROOF.md'),'script_sha256':sha(__file__)},indent=2))
if __name__=='__main__':main()
